(function(){const A=[{"id":"sp5-maloe-chudo-zvezd","n":"Малое Чудо Звёзд","l":0,"sc":"Прорицание","t":"1 действие","r":"9 м","c":"В","m":"","d":"До 1 часа","conc":false,"rit":false,"dmg":"—","cl":["Бард","Жрец","Друид"],"ds":"Вы творите мелкое чудо: указать север, высветить созвездие на потолке или узнать, сколько до рассвета. Одновременно активны не более трёх эффектов; вы можете окончить любой действием.","save":"","atk":false,"mech":"Малое Чудо","theme":"Звёзд","orig":true,"pack":"spells5.js"},{"id":"sp5-legion-razuma","n":"Легион Разума","l":5,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВСМ","m":"Кусочек мозгового коралла.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"2к6 психический","cl":["Колдун","Следопыт","Волшебник"],"ds":"Появляются четыре духа (разума): Маленькие, КД 15, хиты 20, скорость 12 м, иммунитет к урону «психический». Каждый атакует заклинанием 1,5 м на 2к6 урона (психический). Действуют в вашу инициативу по вашим мысленным командам (без действия). На больших уровнях: +1 дух за каждый уровень ячейки выше 5-го.","save":"","atk":true,"mech":"Легион","theme":"Разума","orig":true,"pack":"spells5.js"},{"id":"sp5-pechat-yada","n":"Печать Яда","l":2,"sc":"Ограждение","t":"10 минут","r":"Касание","c":"ВСМ","m":"Жало пчелы.","d":"8 часов","conc":false,"rit":true,"dmg":"3к6 яд","cl":["Изобретатель","Паладин","Волшебник"],"ds":"Вы чертите печать на поверхности или проходе (до 6 м). Когда существо, не названное вами, пересекает её, вы мысленно пробуждаетесь/узнаёте об этом (если вы в пределах 1,5 км), а нарушитель совершает спасбросок (Телосложение): 3к6 урона (яд) при провале, половина при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 2-го.","save":"Телосложение","atk":false,"mech":"Печать","theme":"Яда","orig":true,"pack":"spells5.js"},{"id":"sp5-kope-voln","n":"Копьё Волн","l":1,"sc":"Вызов","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"2к10 дробящий","cl":["Чародей","Жрец","Друид"],"ds":"Дальнобойная атака заклинанием: при попадании 2к10 урона (дробящий). При критическом попадании копьё пробивает цель и поражает второе существо в 3 м позади неё (обычный бросок атаки). На больших уровнях: +1к10 за каждый уровень ячейки выше 1-го.","save":"","atk":true,"mech":"Копьё","theme":"Волн","orig":true,"pack":"spells5.js"},{"id":"sp5-dvoynik-vetra","n":"Двойник Ветра","l":5,"sc":"Иллюзия","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"4к6 звук","cl":["Следопыт","Друид","Паладин"],"ds":"Вы создаёте двойника из сгущённого воздуха — прозрачного и упругого. Он двигается по вашей воле (бонусное действие, 9 м), вы видите и слышите его органами чувств, и ваши заклинания могут исходить от него. Двойник имеет КД 14 и 1 хит; при уничтожении взрывается: 4к6 урона (звук) в 3 м.","save":"","atk":false,"mech":"Двойник","theme":"Ветра","orig":true,"pack":"spells5.js"},{"id":"sp5-potok-kamnya","n":"Поток Камня","l":3,"sc":"Преобразование","t":"1 действие","r":"На себя (линия 30 м)","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"7к6 дробящий","cl":["Изобретатель","Друид","Волшебник"],"ds":"Линия длиной 30 м и шириной 1,5 м. Существа на линии совершают спасбросок (Сила): 7к6 урона (дробящий) при провале, половина при успехе. Поток игнорирует укрытие на половину и на три четверти. На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Сила","atk":false,"mech":"Поток","theme":"Камня","orig":true,"pack":"spells5.js"},{"id":"sp5-uzy-duhov","n":"Узы Духов","l":1,"sc":"Очарование","t":"1 действие","r":"18 м","c":"ВСМ","m":"Благовония.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"1к4 психический","cl":["Бард","Колдун","Жрец"],"ds":"Узы (духов) охватывают существо: спасбросок (Мудрость) или оно опутано. В конце каждого своего хода цель повторяет спасбросок, оканчивая эффект при успехе. Пока цель опутана, она получает 1к4 урона (психический) в начале каждого своего хода. На больших уровнях: +1 цель за каждый уровень ячейки выше 1-го.","save":"Мудрость","atk":false,"mech":"Узы","theme":"Духов","orig":true,"pack":"spells5.js"},{"id":"sp5-raspad-mirazhey","n":"Распад Миражей","l":6,"sc":"Иллюзия","t":"1 действие","r":"18 м","c":"ВСМ","m":"Кусочек стекла.","d":"Мгновенная","conc":false,"rit":false,"dmg":"10к10 психический","cl":["Бард","Колдун"],"ds":"Существо совершает спасбросок Телосложения: 10к10 урона (психический) при провале, половина при успехе. Существо, у которого хиты опустились до 0, обращается в стихию и может быть возвращено только «Истинным воскрешением» или «Желанием». На больших уровнях: +1к10 за каждый уровень ячейки выше 6-го.","save":"Телосложение","atk":false,"mech":"Распад","theme":"Миражей","orig":true,"pack":"spells5.js"},{"id":"sp5-duh-sveta","n":"Дух Света","l":3,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВСМ","m":"Святой символ.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8+6 излучение","cl":["Жрец","Следопыт","Друид"],"ds":"Вы призываете духа (света) Среднего размера: КД 13 + уровень заклинания, хиты 30 + 10 за уровень выше 3-го, скорость 12 м. Мультиатака: число атак, равное половине уровня заклинания; атака заклинанием +ваш бонус, 1к8 + 3 + уровень урона (излучение). Иммунитет к урону «излучение». Действует сразу после вас. На больших уровнях: +10 хитов и +1 КД за каждый уровень ячейки выше 3-го.","save":"","atk":true,"mech":"Дух","theme":"Света","orig":true,"pack":"spells5.js"},{"id":"sp5-kleymo-shipov","n":"Клеймо Шипов","l":1,"sc":"Преобразование","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 колющий","cl":["Следопыт","Паладин","Изобретатель"],"ds":"Следующее ваше попадание атакой оружием наносит дополнительно 2к6 урона (колющий), и цель совершает спасбросок (Сила) — при провале она опутывается колючими лозами: скорость 0 до конца её следующего хода. На больших уровнях: +1к6 за каждый уровень ячейки выше 1-го.","save":"Сила","atk":false,"mech":"Клеймо","theme":"Шипов","orig":true,"pack":"spells5.js"},{"id":"sp5-avatar-run","n":"Аватар Рун","l":6,"sc":"Преобразование","t":"1 бонусное действие","r":"На себя","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"4к8 силовое поле","cl":["Жрец","Волшебник"],"ds":"Вы становитесь аватаром стихии: иммунитет к урону «силовое поле», полёт 18 м, 30 временных хитов. Бонусным действием в каждый ход вы метаете снаряд (дальнобойная атака заклинанием, 36 м) на 4к8 урона (силовое поле). На больших уровнях: +10 временных хитов за каждый уровень ячейки выше 6-го.","save":"","atk":true,"mech":"Аватар","theme":"Рун","orig":true,"pack":"spells5.js"},{"id":"sp5-aura-vremeni","n":"Аура Времени","l":3,"sc":"Ограждение","t":"1 действие","r":"На себя (3 м)","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 силовое поле","cl":["Бард","Паладин","Следопыт"],"ds":"Вас окружает аура радиусом 3 м. Союзники в ней имеют сопротивление урону «силовое поле» и преимущество на спасброски от эффектов, из-за которых цель замедляется. Враг, начинающий ход в ауре, совершает спасбросок (Мудрость) или получает 2к6 урона (силовое поле). На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Мудрость","atk":false,"mech":"Аура","theme":"Времени","orig":true,"pack":"spells5.js"},{"id":"sp5-golos-teni","n":"Голос Тени","l":1,"sc":"Очарование","t":"1 действие","r":"На себя","c":"В","m":"","d":"10 минут","conc":false,"rit":false,"dmg":"—","cl":["Колдун","Чародей","Бард"],"ds":"Ваш голос наполняется силой стихии (тени). Вы совершаете с преимуществом проверки Харизмы против существ, которые вас слышат; одно из них по вашему выбору совершает спасбросок Мудрости — при провале оно не может солгать вам до конца действия заклинания. По окончании существо знает, что на него влияли. На больших уровнях: +1 существо, которое не может лгать за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Голос","theme":"Тени","orig":true,"pack":"spells5.js"},{"id":"sp5-carstvo-krovi","n":"Царство Крови","l":7,"sc":"Вызов","t":"1 минута","r":"Касание","c":"ВСМ","m":"Капля вашей крови.","d":"1 день","conc":false,"rit":false,"dmg":"—","cl":["Колдун","Жрец"],"ds":"Вы и до 8 существ переноситесь в полуплан стихии (крови) площадью 150 м², где вы задаёте погоду, свет и простой рельеф. Несогласное существо может избежать переноса спасброском Харизмы. По окончании все возвращаются туда, откуда ушли. Ячейкой 9 уровня — постоянно, с единственным входом.","save":"Телосложение","atk":false,"mech":"Царство","theme":"Крови","orig":true,"pack":"spells5.js"},{"id":"sp5-perenos-molniy","n":"Перенос Молний","l":3,"sc":"Вызов","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"—","cl":["Изобретатель","Волшебник","Друид"],"ds":"Вы и до шести согласных существ, держащихся за руки, перемещаетесь по грозовым облакам на расстояние до 150 м в видимое или известное вам место. На больших уровнях: +150 м за каждый уровень ячейки выше 3-го.","save":"","atk":false,"mech":"Перенос","theme":"Молний","orig":true,"pack":"spells5.js"},{"id":"sp5-balzam-groma","n":"Бальзам Грома","l":1,"sc":"Воплощение","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"1 минута","conc":false,"rit":false,"dmg":"—","cl":["Бард","Жрец","Друид"],"ds":"Существо восстанавливает 1к8 + модификатор заклинательной характеристики хитов и получает сопротивление урону «звук» на 1 минуту. Не действует на нежить и конструктов. На больших уровнях: +1к8 за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Бальзам","theme":"Грома","orig":true,"pack":"spells5.js"},{"id":"sp5-slovo-ineya","n":"Слово Инея","l":8,"sc":"Очарование","t":"1 действие","r":"На себя (18 м)","c":"В","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"13к6 холод","cl":["Чародей","Бард"],"ds":"Вы произносите истинное слово (инея). Каждый враг в 18 м, слышащий вас, совершает спасбросок Харизмы: 13к6 урона (холод) и ошеломление до конца вашего следующего хода при провале, половина урона при успехе.","save":"Харизма","atk":false,"mech":"Слово","theme":"Инея","orig":true,"pack":"spells5.js"},{"id":"sp5-oblik-plameni","n":"Облик Пламени","l":4,"sc":"Преобразование","t":"1 действие","r":"На себя","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"2к8 огонь","cl":["Изобретатель","Колдун","Следопыт"],"ds":"Вы принимаете облик (пламени): сопротивление урону «огонь» и немагическому оружию, скорость полёта или лазания 12 м, а действием вы совершаете две рукопашные атаки заклинанием по 2к8 урона (огонь). Попадание: цель загорается: 1к4 урона (огонь) в начале каждого своего хода, пока не потратит действие на тушение. На больших уровнях: +1к8 к одной атаке за каждый уровень ячейки выше 4-го.","save":"","atk":true,"mech":"Облик","theme":"Пламени","orig":true,"pack":"spells5.js"},{"id":"sp5-sfera-kostey","n":"Сфера Костей","l":2,"sc":"Некромантия","t":"1 действие","r":"18 м","c":"ВСМ","m":"Фаланга пальца.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 колющий","cl":["Колдун","Жрец","Волшебник"],"ds":"Сфера (костей) диаметром 1,5 м появляется в пределах дистанции. Существо, оканчивающее ход в 1,5 м от неё, совершает спасбросок (Телосложение): 2к6 урона (колющий) при провале, половина при успехе. Бонусным действием сфера перемещается на 9 м; если она врезается в существо, оно совершает спасбросок, и сфера останавливается. На больших уровнях: +1к6 за каждый уровень ячейки выше 2-го.","save":"Телосложение","atk":false,"mech":"Сфера","theme":"Костей","orig":true,"pack":"spells5.js"},{"id":"sp5-apokalipsis-pustoty","n":"Апокалипсис Пустоты","l":9,"sc":"Вызов","t":"1 действие","r":"1,5 км","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"14к6+14к6 силовое поле","cl":["Чародей","Волшебник"],"ds":"Вы выбираете до четырёх точек; от каждой расходится сфера радиусом 12 м. Существо в одной или нескольких сферах совершает один спасбросок (Харизма): 14к6 урона (силовое поле) плюс 14к6 силовым полем при провале (и цель не может телепортироваться и перемещаться между планами до конца её следующего хода), половина при успехе. Предметы и строения в области получают двойной урон.","save":"Харизма","atk":false,"mech":"Апокалипсис","theme":"Пустоты","orig":true,"pack":"spells5.js"},{"id":"sp5-vrata-zvezd","n":"Врата Звёзд","l":4,"sc":"Ограждение","t":"1 действие","r":"18 м","c":"ВСМ","m":"Щепоть звёздной пыли.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"4к10 излучение","cl":["Бард","Жрец","Чародей"],"ds":"Существо совершает спасбросок Харизмы или проваливается в карман-измерение (звёзд). Там оно недееспособно. Когда заклинание оканчивается, цель возвращается и получает 4к10 урона (излучение). Если концентрация продержалась полную минуту, урон удваивается. На больших уровнях: +1 цель за каждый уровень ячейки выше 4-го.","save":"Харизма","atk":false,"mech":"Врата","theme":"Звёзд","orig":true,"pack":"spells5.js"},{"id":"sp5-zavesa-razuma","n":"Завеса Разума","l":2,"sc":"Очарование","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"—","cl":["Чародей","Бард","Колдун"],"ds":"Куб с ребром 6 м заполняется завесой (разума): местность труднопроходимая и слабо заслонённая. Существо, впервые за ход входящее туда, совершает спасбросок (Интеллект) — при провале оно не может совершать реакции и совершает с помехой следующую проверку Интеллекта. На больших уровнях: +3 м к ребру куба за каждый уровень ячейки выше 2-го.","save":"Интеллект","atk":false,"mech":"Завеса","theme":"Разума","orig":true,"pack":"spells5.js"},{"id":"sp5-kasanie-yada","n":"Касание Яда","l":0,"sc":"Преобразование","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к8 яд","cl":["Изобретатель","Колдун","Друид"],"ds":"Рукопашная атака заклинанием: при попадании 1к8 урона (яд), и цель отравлена до конца своего следующего хода. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"","atk":true,"mech":"Касание","theme":"Яда","orig":true,"pack":"spells5.js"},{"id":"sp5-tropa-voln","n":"Тропа Волн","l":4,"sc":"Преобразование","t":"10 минут","r":"Касание","c":"ВСМ","m":"Морская ракушка.","d":"8 часов","conc":false,"rit":true,"dmg":"—","cl":["Жрец","Друид","Изобретатель"],"ds":"До 8 согласных существ отправляются в путь по течению: группа может дышать водой и плыть со скоростью 18 м. На время действия скорость путешествия группы удваивается, а случайные столкновения в пути случаются вдвое реже.","save":"","atk":false,"mech":"Тропа","theme":"Волн","orig":true,"pack":"spells5.js"},{"id":"sp5-morok-vetra","n":"Морок Ветра","l":2,"sc":"Очарование","t":"1 действие","r":"27 м","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"—","cl":["Чародей","Следопыт","Друид"],"ds":"Существо совершает спасбросок Мудрости. При провале в начале каждого своего хода оно бросает к6: на 1–2 оно атакует ближайшее существо (кроме себя) и больше ничего не делает. В конце хода оно повторяет спасбросок. При каждом провале повторного спасброска цель также отталкивается на 4,5 м в выбранном вами направлении. На больших уровнях: +1 цель за каждый уровень ячейки выше 2-го.","save":"Мудрость","atk":false,"mech":"Морок","theme":"Ветра","orig":true,"pack":"spells5.js"},{"id":"sp5-otmetina-kamnya","n":"Отметина Камня","l":0,"sc":"Преобразование","t":"1 бонусное действие","r":"18 м","c":"С","m":"","d":"1 раунд","conc":false,"rit":false,"dmg":"1к4 дробящий","cl":["Изобретатель","Паладин","Следопыт"],"ds":"Вы отмечаете существо знаком (камня). Первое попадание по нему атакой оружием (вашей или союзника) до конца вашего следующего хода наносит дополнительно 1к4 урона (дробящий). Нельзя накладывать на одно существо чаще раза в раунд. Кость урона растёт до к6, к8 и к10 на 5, 11 и 17 уровнях.","save":"","atk":false,"mech":"Отметина","theme":"Камня","orig":true,"pack":"spells5.js"},{"id":"sp5-kara-duhov","n":"Кара Духов","l":5,"sc":"Вызов","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"8к8 психический","cl":["Бард","Колдун","Жрец"],"ds":"Одно существо совершает спасбросок (Мудрость): 8к8 урона (психический) при провале (и цель испугана вами до конца её следующего хода), половина при успехе. Если урон опускает хиты до 0, цель распадается, становясь прахом стихии. На больших уровнях: +1к8 за каждый уровень ячейки выше 5-го.","save":"Мудрость","atk":false,"mech":"Кара","theme":"Духов","orig":true,"pack":"spells5.js"},{"id":"sp5-strazh-mirazhey","n":"Страж Миражей","l":2,"sc":"Вызов","t":"1 действие","r":"9 м","c":"ВСМ","m":"Кусочек стекла.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8 психический","cl":["Колдун","Волшебник","Следопыт"],"ds":"Вы призываете крошечного духа (миражей): КД 14, хиты 10, полёт 9 м, действует в ваш ход. Он может совершать действие Помощь или атаковать (атака заклинанием, 1,5 м, 1к8 урона (психический)). Реакцией дух бьёт существо, атакующее вас в 1,5 м от него. На больших уровнях: +5 хитов и +1к8 к урону за каждый уровень ячейки выше 2-го.","save":"","atk":true,"mech":"Страж","theme":"Миражей","orig":true,"pack":"spells5.js"},{"id":"sp5-obereg-sveta","n":"Оберег Света","l":0,"sc":"Воплощение","t":"1 реакция (когда вы получаете урон)","r":"На себя","c":"С","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"—","cl":["Паладин","Жрец","Волшебник"],"ds":"Вы уменьшаете полученный урон на 1к6 + модификатор заклинательной характеристики. Если урон был типа «излучение», уменьшение удваивается. Кость растёт до 2к6, 3к6 и 4к6 на 5, 11 и 17 уровнях.","save":"","atk":false,"mech":"Оберег","theme":"Света","orig":true,"pack":"spells5.js"},{"id":"sp5-svyatilische-shipov","n":"Святилище Шипов","l":5,"sc":"Ограждение","t":"10 минут","r":"Касание","c":"ВСМ","m":"Шип розы.","d":"24 часа","conc":false,"rit":false,"dmg":"—","cl":["Паладин","Изобретатель","Волшебник"],"ds":"Область радиусом 15 м становится святилищем стихии. Союзники в ней получают +1 к КД и спасброскам; враги, входящие в область, совершают спасбросок (Сила) — при провале они опутывается колючими лозами: скорость 0 до конца её следующего хода и у них помеха на атаки по союзникам до конца хода. Ячейкой 7+ уровня длится 7 дней, 9 уровня — постоянно.","save":"Сила","atk":false,"mech":"Святилище","theme":"Шипов","orig":true,"pack":"spells5.js"},{"id":"sp5-vzryv-run","n":"Взрыв Рун","l":3,"sc":"Ограждение","t":"1 действие","r":"45 м","c":"ВСМ","m":"Резец и кусочек кости.","d":"Мгновенная","conc":false,"rit":false,"dmg":"6к6 силовое поле","cl":["Изобретатель","Жрец","Чародей"],"ds":"Сфера радиусом 6 м: каждое существо совершает спасбросок (Интеллект), получая 6к6 урона (силовое поле) при провале (и цель получает светящуюся руну: следующая атака по ней до конца вашего следующего хода получает +1к4 к броску) или половину при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Интеллект","atk":false,"mech":"Взрыв","theme":"Рун","orig":true,"pack":"spells5.js"},{"id":"sp5-volna-vremeni","n":"Волна Времени","l":1,"sc":"Преобразование","t":"1 действие","r":"На себя (конус 4,5 м)","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"2к6 силовое поле","cl":["Бард","Изобретатель","Волшебник"],"ds":"Существа в конусе совершают спасбросок (Мудрость): при провале 2к6 урона (силовое поле) и цель замедляется: не может совершать бонусных действий до конца своего следующего хода; при успехе — половина урона без дополнительного эффекта. На больших уровнях: +1к6 за каждый уровень ячейки выше 1-го.","save":"Мудрость","atk":false,"mech":"Волна","theme":"Времени","orig":true,"pack":"spells5.js"},{"id":"sp5-svyaz-teni","n":"Связь Тени","l":5,"sc":"Прорицание","t":"10 минут","r":"Неограниченная","c":"ВСМ","m":"Клочок чёрной ткани.","d":"Концентрация, до 10 минут","conc":true,"rit":true,"dmg":"—","cl":["Следопыт","Колдун","Паладин"],"ds":"Вы вопрошаете тень места или предмета (она видела всё, что происходило рядом), но в любом месте плана, где бывали. Вы видите и слышите место, как если бы находились там, и можете говорить с присутствующими.","save":"","atk":false,"mech":"Связь","theme":"Тени","orig":true,"pack":"spells5.js"},{"id":"sp5-kokon-krovi","n":"Кокон Крови","l":3,"sc":"Ограждение","t":"1 действие","r":"18 м","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"—","cl":["Чародей","Колдун","Жрец"],"ds":"Кокон (крови) окружает существо. Согласное существо получает полное укрытие и 2к10 временных хитов. Несогласное совершает спасбросок (Телосложение) — при провале оно опутано, имеет полное укрытие и не может колдовать заклинания с соматическим компонентом; в конце каждого хода повторяет спасбросок. На больших уровнях: +1 цель за каждый уровень ячейки выше 3-го.","save":"Телосложение","atk":false,"mech":"Кокон","theme":"Крови","orig":true,"pack":"spells5.js"},{"id":"sp5-pokrov-molniy","n":"Покров Молний","l":1,"sc":"Ограждение","t":"1 действие","r":"На себя","c":"ВСМ","m":"Кусочек янтаря.","d":"1 час","conc":false,"rit":false,"dmg":"5 электричество","cl":["Изобретатель","Паладин","Волшебник"],"ds":"Вы получаете 5 временных хитов. Пока они есть, существо, попавшее по вам рукопашной атакой, получает 5 урона (электричество); у вас сопротивление урону «электричество». На больших уровнях: +5 временных хитов и +5 ответного урона за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Покров","theme":"Молний","orig":true,"pack":"spells5.js"},{"id":"sp5-kolco-groma","n":"Кольцо Грома","l":6,"sc":"Воплощение","t":"1 действие","r":"45 м","c":"ВСМ","m":"Маленький колокольчик.","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"6к8 звук","cl":["Чародей","Бард"],"ds":"Кольцо радиусом до 18 м. Существо внутри не может пересечь кольцо без спасброска (Телосложение): при провале оно получает 6к8 урона (звук), не проходит и отбрасывается на 3 м от источника и не может совершать реакции до начала своего хода; при успехе — половина урона и проходит. Вы выбираете существ, которых кольцо пропускает. На больших уровнях: +1к8 за каждый уровень ячейки выше 6-го.","save":"Телосложение","atk":false,"mech":"Кольцо","theme":"Грома","orig":true,"pack":"spells5.js"},{"id":"sp5-ubezhische-ineya","n":"Убежище Инея","l":3,"sc":"Ограждение","t":"1 минута","r":"На себя (полусфера 3 м)","c":"ВСМ","m":"Кристалл льда.","d":"8 часов","conc":false,"rit":true,"dmg":"—","cl":["Паладин","Бард","Друид"],"ds":"Над вами возникает неподвижное убежище для 9 Средних существ: ледяной купол, внутри ровная температура, снаружи он неотличим от сугроба. Существа и предметы внутри при сотворении могут свободно выходить и входить; прочие — нет. Магия не проходит сквозь стены.","save":"","atk":false,"mech":"Убежище","theme":"Инея","orig":true,"pack":"spells5.js"},{"id":"sp5-chute-plameni","n":"Чутьё Пламени","l":1,"sc":"Прорицание","t":"1 действие","r":"На себя (9 м)","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":true,"dmg":"—","cl":["Колдун","Изобретатель","Бард"],"ds":"Вы чувствуете источники огня, горючие вещества и существ с иммунитетом к огню в пределах 9 м и знаете их направление. Чутьё проходит сквозь большинство преград, но блокируется 30 см камня, 2,5 см металла или тонким листом свинца.","save":"","atk":false,"mech":"Чутьё","theme":"Пламени","orig":true,"pack":"spells5.js"},{"id":"sp5-avatar-kostey","n":"Аватар Костей","l":6,"sc":"Преобразование","t":"1 бонусное действие","r":"На себя","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"4к8 колющий","cl":["Колдун","Жрец"],"ds":"Вы становитесь аватаром стихии: иммунитет к урону «колющий», полёт 18 м, 30 временных хитов. Бонусным действием в каждый ход вы метаете снаряд (дальнобойная атака заклинанием, 36 м) на 4к8 урона (колющий). На больших уровнях: +10 временных хитов за каждый уровень ячейки выше 6-го.","save":"","atk":true,"mech":"Аватар","theme":"Костей","orig":true,"pack":"spells5.js"},{"id":"sp5-aura-pustoty","n":"Аура Пустоты","l":3,"sc":"Ограждение","t":"1 действие","r":"На себя (3 м)","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 силовое поле","cl":["Паладин","Следопыт","Бард"],"ds":"Вас окружает аура радиусом 3 м. Союзники в ней имеют сопротивление урону «силовое поле» и преимущество на спасброски от эффектов, из-за которых цель не может телепортироваться и перемещаться между планами до конца её следующего хода. Враг, начинающий ход в ауре, совершает спасбросок (Харизма) или получает 2к6 урона (силовое поле). На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Харизма","atk":false,"mech":"Аура","theme":"Пустоты","orig":true,"pack":"spells5.js"},{"id":"sp5-golos-zvezd","n":"Голос Звёзд","l":1,"sc":"Очарование","t":"1 действие","r":"На себя","c":"В","m":"","d":"10 минут","conc":false,"rit":false,"dmg":"—","cl":["Бард","Жрец","Чародей"],"ds":"Ваш голос наполняется силой стихии (звёзд). Вы совершаете с преимуществом проверки Харизмы против существ, которые вас слышат; одно из них по вашему выбору совершает спасбросок Мудрости — при провале оно не может солгать вам до конца действия заклинания. По окончании существо знает, что на него влияли. На больших уровнях: +1 существо, которое не может лгать за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Голос","theme":"Звёзд","orig":true,"pack":"spells5.js"},{"id":"sp5-carstvo-razuma","n":"Царство Разума","l":7,"sc":"Вызов","t":"1 минута","r":"Касание","c":"ВСМ","m":"Кусочек мозгового коралла.","d":"1 день","conc":false,"rit":false,"dmg":"—","cl":["Бард","Колдун"],"ds":"Вы и до 8 существ переноситесь в полуплан стихии (разума) площадью 150 м², где вы задаёте погоду, свет и простой рельеф. Несогласное существо может избежать переноса спасброском Харизмы. По окончании все возвращаются туда, откуда ушли. Ячейкой 9 уровня — постоянно, с единственным входом.","save":"Интеллект","atk":false,"mech":"Царство","theme":"Разума","orig":true,"pack":"spells5.js"},{"id":"sp5-perenos-yada","n":"Перенос Яда","l":3,"sc":"Вызов","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"—","cl":["Следопыт","Изобретатель","Колдун"],"ds":"Вы и до шести согласных существ, держащихся за руки, перемещаетесь сквозь болота на расстояние до 150 м в видимое или известное вам место. На больших уровнях: +150 м за каждый уровень ячейки выше 3-го.","save":"","atk":false,"mech":"Перенос","theme":"Яда","orig":true,"pack":"spells5.js"},{"id":"sp5-balzam-voln","n":"Бальзам Волн","l":1,"sc":"Воплощение","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"1 минута","conc":false,"rit":false,"dmg":"—","cl":["Жрец","Друид","Следопыт"],"ds":"Существо восстанавливает 1к8 + модификатор заклинательной характеристики хитов и получает сопротивление урону «дробящий» на 1 минуту. Не действует на нежить и конструктов. На больших уровнях: +1к8 за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Бальзам","theme":"Волн","orig":true,"pack":"spells5.js"},{"id":"sp5-slovo-vetra","n":"Слово Ветра","l":8,"sc":"Очарование","t":"1 действие","r":"На себя (18 м)","c":"В","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"13к6 звук","cl":["Чародей","Бард"],"ds":"Вы произносите истинное слово (ветра). Каждый враг в 18 м, слышащий вас, совершает спасбросок Харизмы: 13к6 урона (звук) и ошеломление до конца вашего следующего хода при провале, половина урона при успехе.","save":"Харизма","atk":false,"mech":"Слово","theme":"Ветра","orig":true,"pack":"spells5.js"},{"id":"sp5-oblik-kamnya","n":"Облик Камня","l":4,"sc":"Преобразование","t":"1 действие","r":"На себя","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"2к8 дробящий","cl":["Изобретатель","Друид","Волшебник"],"ds":"Вы принимаете облик (камня): сопротивление урону «дробящий» и немагическому оружию, скорость полёта или лазания 12 м, а действием вы совершаете две рукопашные атаки заклинанием по 2к8 урона (дробящий). Попадание: цель сбивается с ног, если она Большая или меньше. На больших уровнях: +1к8 к одной атаке за каждый уровень ячейки выше 4-го.","save":"","atk":true,"mech":"Облик","theme":"Камня","orig":true,"pack":"spells5.js"},{"id":"sp5-cep-duhov","n":"Цепь Духов","l":2,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"3к8 психический","cl":["Бард","Колдун","Жрец"],"ds":"Дальнобойная атака заклинанием: 3к8 урона (психический) при попадании. Затем цепь перескакивает на второе существо в 3 м от первой цели: оно совершает спасбросок (Мудрость) или получает половину этого урона. На больших уровнях: +1к8 и +1 перескок за каждый уровень ячейки выше 2-го.","save":"Мудрость","atk":true,"mech":"Цепь","theme":"Духов","orig":true,"pack":"spells5.js"},{"id":"sp5-iskra-mirazhey","n":"Искра Миражей","l":0,"sc":"Иллюзия","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к10 психический","cl":["Колдун","Бард","Волшебник"],"ds":"Дальнобойная атака заклинанием по существу или предмету: при попадании 1к10 урона (психический). Предмет, который никто не несёт, получает двойной урон. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"","atk":true,"mech":"Искра","theme":"Миражей","orig":true,"pack":"spells5.js"},{"id":"sp5-stena-sveta","n":"Стена Света","l":4,"sc":"Воплощение","t":"1 действие","r":"36 м","c":"ВСМ","m":"Святой символ.","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"5к8 излучение","cl":["Паладин","Жрец","Чародей"],"ds":"Стена (света) длиной до 18 м, высотой 6 м и толщиной 30 см (или кольцо диаметром 6 м). Существо, впервые за ход проходящее сквозь стену или оканчивающее ход в ней, совершает спасбросок (Телосложение): 5к8 урона (излучение) при провале (и цель излучает тусклый свет в 1,5 м и не может стать невидимой до конца её следующего хода), половина при успехе. Стена — слабо заслоняет обзор. На больших уровнях: +1к8 за каждый уровень ячейки выше 4-го.","save":"Телосложение","atk":false,"mech":"Стена","theme":"Света","orig":true,"pack":"spells5.js"},{"id":"sp5-oruzhie-shipov","n":"Оружие Шипов","l":2,"sc":"Преобразование","t":"1 бонусное действие","r":"Касание","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к6 колющий","cl":["Следопыт","Паладин","Изобретатель"],"ds":"Немагическое оружие становится магическим с бонусом +1 к атаке и наносит дополнительно 1к6 урона (колющий). Один раз в ход при попадании владелец может заставить цель совершить спасбросок (Сила): при провале она опутывается колючими лозами: скорость 0 до конца её следующего хода. Ячейкой 4–5 уровня бонус +2, 6+ уровня — +3.","save":"","atk":false,"mech":"Оружие","theme":"Шипов","orig":true,"pack":"spells5.js"},{"id":"sp5-vspyshka-run","n":"Вспышка Рун","l":0,"sc":"Ограждение","t":"1 действие","r":"На себя (1,5 м)","c":"С","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к6 силовое поле","cl":["Изобретатель","Жрец","Волшебник"],"ds":"Каждое существо по вашему выбору в пределах 1,5 м совершает спасбросок (Интеллект), получая 1к6 урона (силовое поле) при провале. Не требует видеть цели. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"Интеллект","atk":false,"mech":"Вспышка","theme":"Рун","orig":true,"pack":"spells5.js"},{"id":"sp5-proklyatie-vremeni","n":"Проклятие Времени","l":4,"sc":"Некромантия","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"2к6 силовое поле","cl":["Бард","Паладин","Волшебник"],"ds":"Цель совершает спасбросок Мудрости. При провале ваши атаки и заклинания наносят ей дополнительно 2к6 урона (силовое поле), а в начале каждого её хода она бросает к4: на 1 она замедляется: не может совершать бонусных действий до конца своего следующего хода. «Снятие проклятия» оканчивает эффект. Ячейкой 5 уровня — 8 часов без концентрации, 7+ уровня — 24 часа.","save":"Мудрость","atk":false,"mech":"Проклятие","theme":"Времени","orig":true,"pack":"spells5.js"},{"id":"sp5-slepok-teni","n":"Слепок Тени","l":2,"sc":"Преобразование","t":"1 минута","r":"Касание","c":"ВСМ","m":"Клочок чёрной ткани.","d":"8 часов","conc":false,"rit":false,"dmg":"—","cl":["Следопыт","Колдун","Волшебник"],"ds":"Вы создаёте немагический предмет из отвердевшей тени, почти невесомой размером до куба 1,5 м: инструмент, мост, лестницу, ящик или простое оружие. Предмет имеет КД 15 и 30 хитов; через 8 часов он рассыпается. Ячейкой 4+ уровня предмет держится 24 часа, 6+ уровня — постоянно.","save":"","atk":false,"mech":"Слепок","theme":"Тени","orig":true,"pack":"spells5.js"},{"id":"sp5-maloe-chudo-krovi","n":"Малое Чудо Крови","l":0,"sc":"Некромантия","t":"1 действие","r":"9 м","c":"В","m":"","d":"До 1 часа","conc":false,"rit":false,"dmg":"—","cl":["Жрец","Колдун","Паладин"],"ds":"Вы творите мелкое чудо: остановить кровотечение у существа, узнать, чья перед вами кровь (если видели это существо), или окрасить ткань в багровый цвет. Одновременно активны не более трёх эффектов; вы можете окончить любой действием.","save":"","atk":false,"mech":"Малое Чудо","theme":"Крови","orig":true,"pack":"spells5.js"},{"id":"sp5-legion-molniy","n":"Легион Молний","l":5,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВСМ","m":"Кусочек янтаря.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"2к6 электричество","cl":["Следопыт","Друид","Волшебник"],"ds":"Появляются четыре духа (молний): Маленькие, КД 15, хиты 20, скорость 12 м, иммунитет к урону «электричество». Каждый атакует заклинанием 1,5 м на 2к6 урона (электричество). Действуют в вашу инициативу по вашим мысленным командам (без действия). На больших уровнях: +1 дух за каждый уровень ячейки выше 5-го.","save":"","atk":true,"mech":"Легион","theme":"Молний","orig":true,"pack":"spells5.js"},{"id":"sp5-pechat-groma","n":"Печать Грома","l":2,"sc":"Ограждение","t":"10 минут","r":"Касание","c":"ВСМ","m":"Маленький колокольчик.","d":"8 часов","conc":false,"rit":true,"dmg":"3к6 звук","cl":["Жрец","Паладин","Изобретатель"],"ds":"Вы чертите печать на поверхности или проходе (до 6 м). Когда существо, не названное вами, пересекает её, вы мысленно пробуждаетесь/узнаёте об этом (если вы в пределах 1,5 км), а нарушитель совершает спасбросок (Телосложение): 3к6 урона (звук) при провале, половина при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 2-го.","save":"Телосложение","atk":false,"mech":"Печать","theme":"Грома","orig":true,"pack":"spells5.js"},{"id":"sp5-kope-ineya","n":"Копьё Инея","l":1,"sc":"Воплощение","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"2к10 холод","cl":["Чародей","Друид","Бард"],"ds":"Дальнобойная атака заклинанием: при попадании 2к10 урона (холод). При критическом попадании копьё пробивает цель и поражает второе существо в 3 м позади неё (обычный бросок атаки). На больших уровнях: +1к10 за каждый уровень ячейки выше 1-го.","save":"","atk":true,"mech":"Копьё","theme":"Инея","orig":true,"pack":"spells5.js"},{"id":"sp5-dvoynik-plameni","n":"Двойник Пламени","l":5,"sc":"Иллюзия","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"4к6 огонь","cl":["Изобретатель","Колдун","Бард"],"ds":"Вы создаёте двойника из закалённого обсидиана, тёплого на ощупь. Он двигается по вашей воле (бонусное действие, 9 м), вы видите и слышите его органами чувств, и ваши заклинания могут исходить от него. Двойник имеет КД 14 и 1 хит; при уничтожении взрывается: 4к6 урона (огонь) в 3 м.","save":"","atk":false,"mech":"Двойник","theme":"Пламени","orig":true,"pack":"spells5.js"},{"id":"sp5-vzryv-kostey","n":"Взрыв Костей","l":3,"sc":"Некромантия","t":"1 действие","r":"45 м","c":"ВСМ","m":"Фаланга пальца.","d":"Мгновенная","conc":false,"rit":false,"dmg":"6к6 колющий","cl":["Колдун","Жрец","Чародей"],"ds":"Сфера радиусом 6 м: каждое существо совершает спасбросок (Телосложение), получая 6к6 урона (колющий) при провале (и цель становится хрупкой: следующий дробящий урон по ней до конца её следующего хода увеличивается на 1к6) или половину при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Телосложение","atk":false,"mech":"Взрыв","theme":"Костей","orig":true,"pack":"spells5.js"},{"id":"sp5-volna-pustoty","n":"Волна Пустоты","l":1,"sc":"Вызов","t":"1 действие","r":"На себя (конус 4,5 м)","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"2к6 силовое поле","cl":["Чародей","Колдун","Волшебник"],"ds":"Существа в конусе совершают спасбросок (Харизма): при провале 2к6 урона (силовое поле) и цель не может телепортироваться и перемещаться между планами до конца её следующего хода; при успехе — половина урона без дополнительного эффекта. На больших уровнях: +1к6 за каждый уровень ячейки выше 1-го.","save":"Харизма","atk":false,"mech":"Волна","theme":"Пустоты","orig":true,"pack":"spells5.js"},{"id":"sp5-svyaz-zvezd","n":"Связь Звёзд","l":5,"sc":"Прорицание","t":"10 минут","r":"Неограниченная","c":"ВСМ","m":"Щепоть звёздной пыли.","d":"Концентрация, до 10 минут","conc":true,"rit":true,"dmg":"—","cl":["Бард","Жрец","Друид"],"ds":"Вы вопрошаете звёзды над головой (они предсказывают ближайшее событие), но в любом месте плана, где бывали. Вы видите и слышите место, как если бы находились там, и можете говорить с присутствующими.","save":"","atk":false,"mech":"Связь","theme":"Звёзд","orig":true,"pack":"spells5.js"},{"id":"sp5-kokon-razuma","n":"Кокон Разума","l":3,"sc":"Ограждение","t":"1 действие","r":"18 м","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"—","cl":["Бард","Чародей","Колдун"],"ds":"Кокон (разума) окружает существо. Согласное существо получает полное укрытие и 2к10 временных хитов. Несогласное совершает спасбросок (Интеллект) — при провале оно опутано, имеет полное укрытие и не может колдовать заклинания с соматическим компонентом; в конце каждого хода повторяет спасбросок. На больших уровнях: +1 цель за каждый уровень ячейки выше 3-го.","save":"Интеллект","atk":false,"mech":"Кокон","theme":"Разума","orig":true,"pack":"spells5.js"},{"id":"sp5-pokrov-yada","n":"Покров Яда","l":1,"sc":"Ограждение","t":"1 действие","r":"На себя","c":"ВСМ","m":"Жало пчелы.","d":"1 час","conc":false,"rit":false,"dmg":"5 яд","cl":["Изобретатель","Паладин","Жрец"],"ds":"Вы получаете 5 временных хитов. Пока они есть, существо, попавшее по вам рукопашной атакой, получает 5 урона (яд); у вас сопротивление урону «яд». На больших уровнях: +5 временных хитов и +5 ответного урона за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Покров","theme":"Яда","orig":true,"pack":"spells5.js"},{"id":"sp5-kolco-voln","n":"Кольцо Волн","l":6,"sc":"Вызов","t":"1 действие","r":"45 м","c":"ВСМ","m":"Морская ракушка.","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"6к8 дробящий","cl":["Чародей","Жрец"],"ds":"Кольцо радиусом до 18 м. Существо внутри не может пересечь кольцо без спасброска (Сила): при провале оно получает 6к8 урона (дробящий), не проходит и промокает и сбивается с ног; до конца её следующего хода она уязвима к электричеству; при успехе — половина урона и проходит. Вы выбираете существ, которых кольцо пропускает. На больших уровнях: +1к8 за каждый уровень ячейки выше 6-го.","save":"Сила","atk":false,"mech":"Кольцо","theme":"Волн","orig":true,"pack":"spells5.js"},{"id":"sp5-ubezhische-vetra","n":"Убежище Ветра","l":3,"sc":"Ограждение","t":"1 минута","r":"На себя (полусфера 3 м)","c":"ВСМ","m":"Перо.","d":"8 часов","conc":false,"rit":true,"dmg":"—","cl":["Следопыт","Друид","Паладин"],"ds":"Над вами возникает неподвижное убежище для 9 Средних существ: вихревая стена, отклоняющая стрелы и снаряды (помеха на дальнобойные атаки внутрь). Существа и предметы внутри при сотворении могут свободно выходить и входить; прочие — нет. Магия не проходит сквозь стены.","save":"","atk":false,"mech":"Убежище","theme":"Ветра","orig":true,"pack":"spells5.js"},{"id":"sp5-chute-kamnya","n":"Чутьё Камня","l":1,"sc":"Прорицание","t":"1 действие","r":"На себя (9 м)","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":true,"dmg":"—","cl":["Изобретатель","Друид","Следопыт"],"ds":"Вы чувствуете пустоты в камне, тайные ходы, руду и драгоценные камни в пределах 9 м и знаете их направление. Чутьё проходит сквозь большинство преград, но блокируется 30 см камня, 2,5 см металла или тонким листом свинца.","save":"","atk":false,"mech":"Чутьё","theme":"Камня","orig":true,"pack":"spells5.js"},{"id":"sp5-katastrofa-duhov","n":"Катастрофа Духов","l":7,"sc":"Вызов","t":"1 действие","r":"300 м","c":"ВСМ","m":"Благовония.","d":"Мгновенная","conc":false,"rit":false,"dmg":"12к6 психический","cl":["Бард","Колдун"],"ds":"Сфера радиусом 12 м: существа совершают спасбросок (Мудрость) — 12к6 урона (психический) при провале (и цель испугана вами до конца её следующего хода), половина при успехе. Местность становится труднопроходимой на 1 час. На больших уровнях: +1к6 за каждый уровень ячейки выше 7-го.","save":"Мудрость","atk":false,"mech":"Катастрофа","theme":"Духов","orig":true,"pack":"spells5.js"},{"id":"sp5-opros-mirazhey","n":"Опрос Миражей","l":3,"sc":"Прорицание","t":"10 минут","r":"Касание","c":"ВСМ","m":"Кусочек стекла.","d":"10 минут","conc":false,"rit":true,"dmg":"—","cl":["Бард","Колдун","Волшебник"],"ds":"Вы обращаетесь к стихии: вопрошаете отражение в воде или зеркале (оно показывает сцену, которую видело). Вы можете задать до трёх вопросов и получаете короткие правдивые ответы, ограниченные тем, что могла «видеть» стихия.","save":"","atk":false,"mech":"Опрос","theme":"Миражей","orig":true,"pack":"spells5.js"},{"id":"sp5-shag-sveta","n":"Шаг Света","l":1,"sc":"Вызов","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к6 излучение","cl":["Паладин","Жрец","Друид"],"ds":"Вы телепортируетесь на 9 м в видимое свободное место. Каждое существо в 1,5 м от точки отправления совершает спасбросок (Телосложение) или получает 1к6 урона (излучение). На больших уровнях: +3 м дистанции и +1к6 за каждый уровень ячейки выше 1-го.","save":"Телосложение","atk":false,"mech":"Шаг","theme":"Света","orig":true,"pack":"spells5.js"},{"id":"sp5-vlast-shipov","n":"Власть Шипов","l":8,"sc":"Преобразование","t":"1 действие","r":"На себя (1,5 км)","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"6к10 колющий","cl":["Друид","Чародей"],"ds":"Вы повелеваете стихией (шипов) в радиусе 1,5 км: создаёте, гасите, перемещаете и формируете её проявления. Действием вы обрушиваете её на существо в 36 м: спасбросок (Сила), 6к10 урона (колющий) при провале и цель опутывается колючими лозами: скорость 0 до конца её следующего хода, половина при успехе.","save":"Сила","atk":false,"mech":"Власть","theme":"Шипов","orig":true,"pack":"spells5.js"},{"id":"sp5-burya-run","n":"Буря Рун","l":4,"sc":"Ограждение","t":"1 действие","r":"90 м","c":"ВСМ","m":"Резец и кусочек кости.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"3к6 силовое поле","cl":["Изобретатель","Чародей","Жрец"],"ds":"Буря (рун) в цилиндре радиусом 6 м и высотой 12 м: местность труднопроходимая. Существо, начинающее ход в буре или впервые входящее в неё за ход, совершает спасбросок (Интеллект): 3к6 урона (силовое поле) при провале, половина при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 4-го.","save":"Интеллект","atk":false,"mech":"Буря","theme":"Рун","orig":true,"pack":"spells5.js"},{"id":"sp5-sfera-vremeni","n":"Сфера Времени","l":2,"sc":"Преобразование","t":"1 действие","r":"18 м","c":"ВСМ","m":"Песчинка из песочных часов.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 силовое поле","cl":["Бард","Изобретатель","Волшебник"],"ds":"Сфера (времени) диаметром 1,5 м появляется в пределах дистанции. Существо, оканчивающее ход в 1,5 м от неё, совершает спасбросок (Мудрость): 2к6 урона (силовое поле) при провале, половина при успехе. Бонусным действием сфера перемещается на 9 м; если она врезается в существо, оно совершает спасбросок, и сфера останавливается. На больших уровнях: +1к6 за каждый уровень ячейки выше 2-го.","save":"Мудрость","atk":false,"mech":"Сфера","theme":"Времени","orig":true,"pack":"spells5.js"},{"id":"sp5-apokalipsis-teni","n":"Апокалипсис Тени","l":9,"sc":"Иллюзия","t":"1 действие","r":"1,5 км","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"14к6+14к6 некротика","cl":["Волшебник","Колдун"],"ds":"Вы выбираете до четырёх точек; от каждой расходится сфера радиусом 12 м. Существо в одной или нескольких сферах совершает один спасбросок (Мудрость): 14к6 урона (некротика) плюс 14к6 силовым полем при провале (и цель окутывается тенью: помеха на проверки Мудрости (Восприятие) и атаки по существам дальше 9 м), половина при успехе. Предметы и строения в области получают двойной урон.","save":"Мудрость","atk":false,"mech":"Апокалипсис","theme":"Тени","orig":true,"pack":"spells5.js"},{"id":"sp5-vrata-krovi","n":"Врата Крови","l":4,"sc":"Ограждение","t":"1 действие","r":"18 м","c":"ВСМ","m":"Капля вашей крови.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"4к10 некротика","cl":["Чародей","Колдун","Жрец"],"ds":"Существо совершает спасбросок Харизмы или проваливается в карман-измерение (крови). Там оно недееспособно. Когда заклинание оканчивается, цель возвращается и получает 4к10 урона (некротика). Если концентрация продержалась полную минуту, урон удваивается. На больших уровнях: +1 цель за каждый уровень ячейки выше 4-го.","save":"Харизма","atk":false,"mech":"Врата","theme":"Крови","orig":true,"pack":"spells5.js"},{"id":"sp5-zavesa-molniy","n":"Завеса Молний","l":2,"sc":"Воплощение","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"—","cl":["Чародей","Друид","Волшебник"],"ds":"Куб с ребром 6 м заполняется завесой (молний): местность труднопроходимая и слабо заслонённая. Существо, впервые за ход входящее туда, совершает спасбросок (Ловкость) — при провале оно не может совершать реакции до начала своего следующего хода. На больших уровнях: +3 м к ребру куба за каждый уровень ячейки выше 2-го.","save":"Ловкость","atk":false,"mech":"Завеса","theme":"Молний","orig":true,"pack":"spells5.js"},{"id":"sp5-kasanie-groma","n":"Касание Грома","l":0,"sc":"Воплощение","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к8 звук","cl":["Жрец","Бард","Чародей"],"ds":"Рукопашная атака заклинанием: при попадании 1к8 урона (звук), и цель отбрасывается на 3 м от источника и не может совершать реакции до начала своего хода. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"","atk":true,"mech":"Касание","theme":"Грома","orig":true,"pack":"spells5.js"},{"id":"sp5-tropa-ineya","n":"Тропа Инея","l":4,"sc":"Преобразование","t":"10 минут","r":"Касание","c":"ВСМ","m":"Кристалл льда.","d":"8 часов","conc":false,"rit":true,"dmg":"—","cl":["Изобретатель","Друид","Паладин"],"ds":"До 8 согласных существ отправляются в путь по льду и снегу: группа скользит по замёрзшей поверхности, не оставляя следов. На время действия скорость путешествия группы удваивается, а случайные столкновения в пути случаются вдвое реже.","save":"","atk":false,"mech":"Тропа","theme":"Инея","orig":true,"pack":"spells5.js"},{"id":"sp5-morok-plameni","n":"Морок Пламени","l":2,"sc":"Очарование","t":"1 действие","r":"27 м","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"—","cl":["Чародей","Колдун","Волшебник"],"ds":"Существо совершает спасбросок Мудрости. При провале в начале каждого своего хода оно бросает к6: на 1–2 оно атакует ближайшее существо (кроме себя) и больше ничего не делает. В конце хода оно повторяет спасбросок. При каждом провале повторного спасброска цель также загорается: 1к4 урона (огонь) в начале каждого своего хода, пока не потратит действие на тушение. На больших уровнях: +1 цель за каждый уровень ячейки выше 2-го.","save":"Мудрость","atk":false,"mech":"Морок","theme":"Пламени","orig":true,"pack":"spells5.js"},{"id":"sp5-vspyshka-kostey","n":"Вспышка Костей","l":0,"sc":"Некромантия","t":"1 действие","r":"На себя (1,5 м)","c":"С","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к6 колющий","cl":["Жрец","Колдун","Волшебник"],"ds":"Каждое существо по вашему выбору в пределах 1,5 м совершает спасбросок (Телосложение), получая 1к6 урона (колющий) при провале. Не требует видеть цели. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"Телосложение","atk":false,"mech":"Вспышка","theme":"Костей","orig":true,"pack":"spells5.js"},{"id":"sp5-proklyatie-pustoty","n":"Проклятие Пустоты","l":4,"sc":"Некромантия","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"2к6 силовое поле","cl":["Чародей","Колдун","Паладин"],"ds":"Цель совершает спасбросок Мудрости. При провале ваши атаки и заклинания наносят ей дополнительно 2к6 урона (силовое поле), а в начале каждого её хода она бросает к4: на 1 она не может телепортироваться и перемещаться между планами до конца её следующего хода. «Снятие проклятия» оканчивает эффект. Ячейкой 5 уровня — 8 часов без концентрации, 7+ уровня — 24 часа.","save":"Мудрость","atk":false,"mech":"Проклятие","theme":"Пустоты","orig":true,"pack":"spells5.js"},{"id":"sp5-slepok-zvezd","n":"Слепок Звёзд","l":2,"sc":"Преобразование","t":"1 минута","r":"Касание","c":"ВСМ","m":"Щепоть звёздной пыли.","d":"8 часов","conc":false,"rit":false,"dmg":"—","cl":["Бард","Жрец","Друид"],"ds":"Вы создаёте немагический предмет из звёздного металла, светящегося тускло размером до куба 1,5 м: инструмент, мост, лестницу, ящик или простое оружие. Предмет имеет КД 15 и 30 хитов; через 8 часов он рассыпается. Ячейкой 4+ уровня предмет держится 24 часа, 6+ уровня — постоянно.","save":"","atk":false,"mech":"Слепок","theme":"Звёзд","orig":true,"pack":"spells5.js"},{"id":"sp5-maloe-chudo-razuma","n":"Малое Чудо Разума","l":0,"sc":"Очарование","t":"1 действие","r":"9 м","c":"В","m":"","d":"До 1 часа","conc":false,"rit":false,"dmg":"—","cl":["Бард","Колдун","Волшебник"],"ds":"Вы творите мелкое чудо: передать одно короткое мысленное слово существу в 9 м. Одновременно активны не более трёх эффектов; вы можете окончить любой действием.","save":"","atk":false,"mech":"Малое Чудо","theme":"Разума","orig":true,"pack":"spells5.js"},{"id":"sp5-legion-yada","n":"Легион Яда","l":5,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВСМ","m":"Жало пчелы.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"2к6 яд","cl":["Следопыт","Колдун","Друид"],"ds":"Появляются четыре духа (яда): Маленькие, КД 15, хиты 20, скорость 12 м, иммунитет к урону «яд». Каждый атакует заклинанием 1,5 м на 2к6 урона (яд). Действуют в вашу инициативу по вашим мысленным командам (без действия). На больших уровнях: +1 дух за каждый уровень ячейки выше 5-го.","save":"","atk":true,"mech":"Легион","theme":"Яда","orig":true,"pack":"spells5.js"},{"id":"sp5-pechat-voln","n":"Печать Волн","l":2,"sc":"Ограждение","t":"10 минут","r":"Касание","c":"ВСМ","m":"Морская ракушка.","d":"8 часов","conc":false,"rit":true,"dmg":"3к6 дробящий","cl":["Жрец","Паладин","Изобретатель"],"ds":"Вы чертите печать на поверхности или проходе (до 6 м). Когда существо, не названное вами, пересекает её, вы мысленно пробуждаетесь/узнаёте об этом (если вы в пределах 1,5 км), а нарушитель совершает спасбросок (Сила): 3к6 урона (дробящий) при провале, половина при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 2-го.","save":"Сила","atk":false,"mech":"Печать","theme":"Волн","orig":true,"pack":"spells5.js"},{"id":"sp5-kope-vetra","n":"Копьё Ветра","l":1,"sc":"Воплощение","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"2к10 звук","cl":["Чародей","Друид","Бард"],"ds":"Дальнобойная атака заклинанием: при попадании 2к10 урона (звук). При критическом попадании копьё пробивает цель и поражает второе существо в 3 м позади неё (обычный бросок атаки). На больших уровнях: +1к10 за каждый уровень ячейки выше 1-го.","save":"","atk":true,"mech":"Копьё","theme":"Ветра","orig":true,"pack":"spells5.js"},{"id":"sp5-dvoynik-kamnya","n":"Двойник Камня","l":5,"sc":"Иллюзия","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"4к6 дробящий","cl":["Изобретатель","Друид","Следопыт"],"ds":"Вы создаёте двойника из цельного камня. Он двигается по вашей воле (бонусное действие, 9 м), вы видите и слышите его органами чувств, и ваши заклинания могут исходить от него. Двойник имеет КД 14 и 1 хит; при уничтожении взрывается: 4к6 урона (дробящий) в 3 м.","save":"","atk":false,"mech":"Двойник","theme":"Камня","orig":true,"pack":"spells5.js"},{"id":"sp5-potok-duhov","n":"Поток Духов","l":3,"sc":"Вызов","t":"1 действие","r":"На себя (линия 30 м)","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"7к6 психический","cl":["Бард","Колдун","Жрец"],"ds":"Линия длиной 30 м и шириной 1,5 м. Существа на линии совершают спасбросок (Мудрость): 7к6 урона (психический) при провале, половина при успехе. Поток игнорирует укрытие на половину и на три четверти. На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Мудрость","atk":false,"mech":"Поток","theme":"Духов","orig":true,"pack":"spells5.js"},{"id":"sp5-uzy-mirazhey","n":"Узы Миражей","l":1,"sc":"Очарование","t":"1 действие","r":"18 м","c":"ВСМ","m":"Кусочек стекла.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"1к4 психический","cl":["Бард","Колдун","Следопыт"],"ds":"Узы (миражей) охватывают существо: спасбросок (Интеллект) или оно опутано. В конце каждого своего хода цель повторяет спасбросок, оканчивая эффект при успехе. Пока цель опутана, она получает 1к4 урона (психический) в начале каждого своего хода. На больших уровнях: +1 цель за каждый уровень ячейки выше 1-го.","save":"Интеллект","atk":false,"mech":"Узы","theme":"Миражей","orig":true,"pack":"spells5.js"},{"id":"sp5-raspad-sveta","n":"Распад Света","l":6,"sc":"Воплощение","t":"1 действие","r":"18 м","c":"ВСМ","m":"Святой символ.","d":"Мгновенная","conc":false,"rit":false,"dmg":"10к10 излучение","cl":["Чародей","Жрец"],"ds":"Существо совершает спасбросок Телосложения: 10к10 урона (излучение) при провале, половина при успехе. Существо, у которого хиты опустились до 0, обращается в стихию и может быть возвращено только «Истинным воскрешением» или «Желанием». На больших уровнях: +1к10 за каждый уровень ячейки выше 6-го.","save":"Телосложение","atk":false,"mech":"Распад","theme":"Света","orig":true,"pack":"spells5.js"},{"id":"sp5-duh-shipov","n":"Дух Шипов","l":3,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВСМ","m":"Шип розы.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8+6 колющий","cl":["Следопыт","Друид","Волшебник"],"ds":"Вы призываете духа (шипов) Среднего размера: КД 13 + уровень заклинания, хиты 30 + 10 за уровень выше 3-го, скорость 12 м. Мультиатака: число атак, равное половине уровня заклинания; атака заклинанием +ваш бонус, 1к8 + 3 + уровень урона (колющий). Иммунитет к урону «колющий». Действует сразу после вас. На больших уровнях: +10 хитов и +1 КД за каждый уровень ячейки выше 3-го.","save":"","atk":true,"mech":"Дух","theme":"Шипов","orig":true,"pack":"spells5.js"},{"id":"sp5-kleymo-run","n":"Клеймо Рун","l":1,"sc":"Ограждение","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 силовое поле","cl":["Изобретатель","Следопыт","Паладин"],"ds":"Следующее ваше попадание атакой оружием наносит дополнительно 2к6 урона (силовое поле), и цель совершает спасбросок (Интеллект) — при провале она получает светящуюся руну: следующая атака по ней до конца вашего следующего хода получает +1к4 к броску. На больших уровнях: +1к6 за каждый уровень ячейки выше 1-го.","save":"Интеллект","atk":false,"mech":"Клеймо","theme":"Рун","orig":true,"pack":"spells5.js"},{"id":"sp5-avatar-vremeni","n":"Аватар Времени","l":6,"sc":"Преобразование","t":"1 бонусное действие","r":"На себя","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"4к8 силовое поле","cl":["Бард","Волшебник"],"ds":"Вы становитесь аватаром стихии: иммунитет к урону «силовое поле», полёт 18 м, 30 временных хитов. Бонусным действием в каждый ход вы метаете снаряд (дальнобойная атака заклинанием, 36 м) на 4к8 урона (силовое поле). На больших уровнях: +10 временных хитов за каждый уровень ячейки выше 6-го.","save":"","atk":true,"mech":"Аватар","theme":"Времени","orig":true,"pack":"spells5.js"},{"id":"sp5-aura-teni","n":"Аура Тени","l":3,"sc":"Ограждение","t":"1 действие","r":"На себя (3 м)","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 некротика","cl":["Следопыт","Паладин","Бард"],"ds":"Вас окружает аура радиусом 3 м. Союзники в ней имеют сопротивление урону «некротика» и преимущество на спасброски от эффектов, из-за которых цель окутывается тенью. Враг, начинающий ход в ауре, совершает спасбросок (Мудрость) или получает 2к6 урона (некротика). На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Мудрость","atk":false,"mech":"Аура","theme":"Тени","orig":true,"pack":"spells5.js"},{"id":"sp5-golos-krovi","n":"Голос Крови","l":1,"sc":"Очарование","t":"1 действие","r":"На себя","c":"В","m":"","d":"10 минут","conc":false,"rit":false,"dmg":"—","cl":["Чародей","Колдун","Жрец"],"ds":"Ваш голос наполняется силой стихии (крови). Вы совершаете с преимуществом проверки Харизмы против существ, которые вас слышат; одно из них по вашему выбору совершает спасбросок Мудрости — при провале оно не может солгать вам до конца действия заклинания. По окончании существо знает, что на него влияли. На больших уровнях: +1 существо, которое не может лгать за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Голос","theme":"Крови","orig":true,"pack":"spells5.js"},{"id":"sp5-carstvo-molniy","n":"Царство Молний","l":7,"sc":"Вызов","t":"1 минута","r":"Касание","c":"ВСМ","m":"Кусочек янтаря.","d":"1 день","conc":false,"rit":false,"dmg":"—","cl":["Друид","Волшебник"],"ds":"Вы и до 8 существ переноситесь в полуплан стихии (молний) площадью 150 м², где вы задаёте погоду, свет и простой рельеф. Несогласное существо может избежать переноса спасброском Харизмы. По окончании все возвращаются туда, откуда ушли. Ячейкой 9 уровня — постоянно, с единственным входом.","save":"Ловкость","atk":false,"mech":"Царство","theme":"Молний","orig":true,"pack":"spells5.js"},{"id":"sp5-perenos-groma","n":"Перенос Грома","l":3,"sc":"Вызов","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"—","cl":["Бард","Жрец","Друид"],"ds":"Вы и до шести согласных существ, держащихся за руки, перемещаетесь на волне звука на расстояние до 150 м в видимое или известное вам место. На больших уровнях: +150 м за каждый уровень ячейки выше 3-го.","save":"","atk":false,"mech":"Перенос","theme":"Грома","orig":true,"pack":"spells5.js"},{"id":"sp5-balzam-ineya","n":"Бальзам Инея","l":1,"sc":"Воплощение","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"1 минута","conc":false,"rit":false,"dmg":"—","cl":["Друид","Следопыт","Паладин"],"ds":"Существо восстанавливает 1к8 + модификатор заклинательной характеристики хитов и получает сопротивление урону «холод» на 1 минуту. Не действует на нежить и конструктов. На больших уровнях: +1к8 за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Бальзам","theme":"Инея","orig":true,"pack":"spells5.js"},{"id":"sp5-slovo-plameni","n":"Слово Пламени","l":8,"sc":"Очарование","t":"1 действие","r":"На себя (18 м)","c":"В","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"13к6 огонь","cl":["Чародей","Колдун"],"ds":"Вы произносите истинное слово (пламени). Каждый враг в 18 м, слышащий вас, совершает спасбросок Харизмы: 13к6 урона (огонь) и ошеломление до конца вашего следующего хода при провале, половина урона при успехе.","save":"Харизма","atk":false,"mech":"Слово","theme":"Пламени","orig":true,"pack":"spells5.js"},{"id":"sp5-burya-kostey","n":"Буря Костей","l":4,"sc":"Некромантия","t":"1 действие","r":"90 м","c":"ВСМ","m":"Фаланга пальца.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"3к6 колющий","cl":["Колдун","Жрец","Чародей"],"ds":"Буря (костей) в цилиндре радиусом 6 м и высотой 12 м: местность труднопроходимая. Существо, начинающее ход в буре или впервые входящее в неё за ход, совершает спасбросок (Телосложение): 3к6 урона (колющий) при провале, половина при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 4-го.","save":"Телосложение","atk":false,"mech":"Буря","theme":"Костей","orig":true,"pack":"spells5.js"},{"id":"sp5-sfera-pustoty","n":"Сфера Пустоты","l":2,"sc":"Вызов","t":"1 действие","r":"18 м","c":"ВСМ","m":"Чёрная жемчужина.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 силовое поле","cl":["Чародей","Колдун","Волшебник"],"ds":"Сфера (пустоты) диаметром 1,5 м появляется в пределах дистанции. Существо, оканчивающее ход в 1,5 м от неё, совершает спасбросок (Харизма): 2к6 урона (силовое поле) при провале, половина при успехе. Бонусным действием сфера перемещается на 9 м; если она врезается в существо, оно совершает спасбросок, и сфера останавливается. На больших уровнях: +1к6 за каждый уровень ячейки выше 2-го.","save":"Харизма","atk":false,"mech":"Сфера","theme":"Пустоты","orig":true,"pack":"spells5.js"},{"id":"sp5-apokalipsis-zvezd","n":"Апокалипсис Звёзд","l":9,"sc":"Прорицание","t":"1 действие","r":"1,5 км","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"14к6+14к6 излучение","cl":["Бард","Волшебник"],"ds":"Вы выбираете до четырёх точек; от каждой расходится сфера радиусом 12 м. Существо в одной или нескольких сферах совершает один спасбросок (Мудрость): 14к6 урона (излучение) плюс 14к6 силовым полем при провале (и цель очерчивается звёздным светом: атаки по ней совершаются с преимуществом до конца её следующего хода), половина при успехе. Предметы и строения в области получают двойной урон.","save":"Мудрость","atk":false,"mech":"Апокалипсис","theme":"Звёзд","orig":true,"pack":"spells5.js"},{"id":"sp5-vrata-razuma","n":"Врата Разума","l":4,"sc":"Ограждение","t":"1 действие","r":"18 м","c":"ВСМ","m":"Кусочек мозгового коралла.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"4к10 психический","cl":["Чародей","Бард","Колдун"],"ds":"Существо совершает спасбросок Харизмы или проваливается в карман-измерение (разума). Там оно недееспособно. Когда заклинание оканчивается, цель возвращается и получает 4к10 урона (психический). Если концентрация продержалась полную минуту, урон удваивается. На больших уровнях: +1 цель за каждый уровень ячейки выше 4-го.","save":"Харизма","atk":false,"mech":"Врата","theme":"Разума","orig":true,"pack":"spells5.js"},{"id":"sp5-zavesa-yada","n":"Завеса Яда","l":2,"sc":"Преобразование","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"—","cl":["Следопыт","Колдун","Друид"],"ds":"Куб с ребром 6 м заполняется завесой (яда): местность труднопроходимая и слабо заслонённая. Существо, впервые за ход входящее туда, совершает спасбросок (Телосложение) — при провале оно отравлена до конца своего следующего хода. На больших уровнях: +3 м к ребру куба за каждый уровень ячейки выше 2-го.","save":"Телосложение","atk":false,"mech":"Завеса","theme":"Яда","orig":true,"pack":"spells5.js"},{"id":"sp5-kasanie-voln","n":"Касание Волн","l":0,"sc":"Вызов","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к8 дробящий","cl":["Жрец","Чародей","Друид"],"ds":"Рукопашная атака заклинанием: при попадании 1к8 урона (дробящий), и цель промокает и сбивается с ног; до конца её следующего хода она уязвима к электричеству. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"","atk":true,"mech":"Касание","theme":"Волн","orig":true,"pack":"spells5.js"},{"id":"sp5-tropa-vetra","n":"Тропа Ветра","l":4,"sc":"Преобразование","t":"10 минут","r":"Касание","c":"ВСМ","m":"Перо.","d":"8 часов","conc":false,"rit":true,"dmg":"—","cl":["Следопыт","Друид","Паладин"],"ds":"До 8 согласных существ отправляются в путь на ветру: группа парит над землёй со скоростью 18 м. На время действия скорость путешествия группы удваивается, а случайные столкновения в пути случаются вдвое реже.","save":"","atk":false,"mech":"Тропа","theme":"Ветра","orig":true,"pack":"spells5.js"},{"id":"sp5-morok-kamnya","n":"Морок Камня","l":2,"sc":"Очарование","t":"1 действие","r":"27 м","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"—","cl":["Друид","Волшебник","Чародей"],"ds":"Существо совершает спасбросок Мудрости. При провале в начале каждого своего хода оно бросает к6: на 1–2 оно атакует ближайшее существо (кроме себя) и больше ничего не делает. В конце хода оно повторяет спасбросок. При каждом провале повторного спасброска цель также сбивается с ног, если она Большая или меньше. На больших уровнях: +1 цель за каждый уровень ячейки выше 2-го.","save":"Мудрость","atk":false,"mech":"Морок","theme":"Камня","orig":true,"pack":"spells5.js"},{"id":"sp5-otmetina-duhov","n":"Отметина Духов","l":0,"sc":"Вызов","t":"1 бонусное действие","r":"18 м","c":"С","m":"","d":"1 раунд","conc":false,"rit":false,"dmg":"1к4 психический","cl":["Паладин","Следопыт","Изобретатель"],"ds":"Вы отмечаете существо знаком (духов). Первое попадание по нему атакой оружием (вашей или союзника) до конца вашего следующего хода наносит дополнительно 1к4 урона (психический). Нельзя накладывать на одно существо чаще раза в раунд. Кость урона растёт до к6, к8 и к10 на 5, 11 и 17 уровнях.","save":"","atk":false,"mech":"Отметина","theme":"Духов","orig":true,"pack":"spells5.js"},{"id":"sp5-kara-mirazhey","n":"Кара Миражей","l":5,"sc":"Иллюзия","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"8к8 психический","cl":["Бард","Колдун","Изобретатель"],"ds":"Одно существо совершает спасбросок (Интеллект): 8к8 урона (психический) при провале (и цель видит ложные образы: помеха на следующий бросок атаки до конца её следующего хода), половина при успехе. Если урон опускает хиты до 0, цель распадается, становясь прахом стихии. На больших уровнях: +1к8 за каждый уровень ячейки выше 5-го.","save":"Интеллект","atk":false,"mech":"Кара","theme":"Миражей","orig":true,"pack":"spells5.js"},{"id":"sp5-strazh-sveta","n":"Страж Света","l":2,"sc":"Вызов","t":"1 действие","r":"9 м","c":"ВСМ","m":"Святой символ.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8 излучение","cl":["Жрец","Следопыт","Друид"],"ds":"Вы призываете крошечного духа (света): КД 14, хиты 10, полёт 9 м, действует в ваш ход. Он может совершать действие Помощь или атаковать (атака заклинанием, 1,5 м, 1к8 урона (излучение)). Реакцией дух бьёт существо, атакующее вас в 1,5 м от него. На больших уровнях: +5 хитов и +1к8 к урону за каждый уровень ячейки выше 2-го.","save":"","atk":true,"mech":"Страж","theme":"Света","orig":true,"pack":"spells5.js"},{"id":"sp5-obereg-shipov","n":"Оберег Шипов","l":0,"sc":"Преобразование","t":"1 реакция (когда вы получаете урон)","r":"На себя","c":"С","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"—","cl":["Паладин","Жрец","Волшебник"],"ds":"Вы уменьшаете полученный урон на 1к6 + модификатор заклинательной характеристики. Если урон был типа «колющий», уменьшение удваивается. Кость растёт до 2к6, 3к6 и 4к6 на 5, 11 и 17 уровнях.","save":"","atk":false,"mech":"Оберег","theme":"Шипов","orig":true,"pack":"spells5.js"},{"id":"sp5-svyatilische-run","n":"Святилище Рун","l":5,"sc":"Ограждение","t":"10 минут","r":"Касание","c":"ВСМ","m":"Резец и кусочек кости.","d":"24 часа","conc":false,"rit":false,"dmg":"—","cl":["Изобретатель","Паладин","Жрец"],"ds":"Область радиусом 15 м становится святилищем стихии. Союзники в ней получают +1 к КД и спасброскам; враги, входящие в область, совершают спасбросок (Интеллект) — при провале они получает светящуюся руну: следующая атака по ней до конца вашего следующего хода получает +1к4 к броску и у них помеха на атаки по союзникам до конца хода. Ячейкой 7+ уровня длится 7 дней, 9 уровня — постоянно.","save":"Интеллект","atk":false,"mech":"Святилище","theme":"Рун","orig":true,"pack":"spells5.js"},{"id":"sp5-vzryv-vremeni","n":"Взрыв Времени","l":3,"sc":"Преобразование","t":"1 действие","r":"45 м","c":"ВСМ","m":"Песчинка из песочных часов.","d":"Мгновенная","conc":false,"rit":false,"dmg":"6к6 силовое поле","cl":["Бард","Изобретатель","Чародей"],"ds":"Сфера радиусом 6 м: каждое существо совершает спасбросок (Мудрость), получая 6к6 урона (силовое поле) при провале (и цель замедляется: не может совершать бонусных действий до конца своего следующего хода) или половину при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Мудрость","atk":false,"mech":"Взрыв","theme":"Времени","orig":true,"pack":"spells5.js"},{"id":"sp5-volna-teni","n":"Волна Тени","l":1,"sc":"Иллюзия","t":"1 действие","r":"На себя (конус 4,5 м)","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"2к6 некротика","cl":["Колдун","Волшебник","Бард"],"ds":"Существа в конусе совершают спасбросок (Мудрость): при провале 2к6 урона (некротика) и цель окутывается тенью: помеха на проверки Мудрости (Восприятие) и атаки по существам дальше 9 м; при успехе — половина урона без дополнительного эффекта. На больших уровнях: +1к6 за каждый уровень ячейки выше 1-го.","save":"Мудрость","atk":false,"mech":"Волна","theme":"Тени","orig":true,"pack":"spells5.js"},{"id":"sp5-svyaz-krovi","n":"Связь Крови","l":5,"sc":"Прорицание","t":"10 минут","r":"Неограниченная","c":"ВСМ","m":"Капля вашей крови.","d":"Концентрация, до 10 минут","conc":true,"rit":true,"dmg":"—","cl":["Колдун","Жрец","Паладин"],"ds":"Вы вопрошаете каплю крови (она отвечает о существе, которому принадлежала), но в любом месте плана, где бывали. Вы видите и слышите место, как если бы находились там, и можете говорить с присутствующими.","save":"","atk":false,"mech":"Связь","theme":"Крови","orig":true,"pack":"spells5.js"},{"id":"sp5-kokon-molniy","n":"Кокон Молний","l":3,"sc":"Ограждение","t":"1 действие","r":"18 м","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"—","cl":["Чародей","Друид","Следопыт"],"ds":"Кокон (молний) окружает существо. Согласное существо получает полное укрытие и 2к10 временных хитов. Несогласное совершает спасбросок (Ловкость) — при провале оно опутано, имеет полное укрытие и не может колдовать заклинания с соматическим компонентом; в конце каждого хода повторяет спасбросок. На больших уровнях: +1 цель за каждый уровень ячейки выше 3-го.","save":"Ловкость","atk":false,"mech":"Кокон","theme":"Молний","orig":true,"pack":"spells5.js"},{"id":"sp5-pokrov-groma","n":"Покров Грома","l":1,"sc":"Ограждение","t":"1 действие","r":"На себя","c":"ВСМ","m":"Маленький колокольчик.","d":"1 час","conc":false,"rit":false,"dmg":"5 звук","cl":["Жрец","Паладин","Волшебник"],"ds":"Вы получаете 5 временных хитов. Пока они есть, существо, попавшее по вам рукопашной атакой, получает 5 урона (звук); у вас сопротивление урону «звук». На больших уровнях: +5 временных хитов и +5 ответного урона за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Покров","theme":"Грома","orig":true,"pack":"spells5.js"},{"id":"sp5-kolco-ineya","n":"Кольцо Инея","l":6,"sc":"Воплощение","t":"1 действие","r":"45 м","c":"ВСМ","m":"Кристалл льда.","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"6к8 холод","cl":["Чародей","Волшебник"],"ds":"Кольцо радиусом до 18 м. Существо внутри не может пересечь кольцо без спасброска (Телосложение): при провале оно получает 6к8 урона (холод), не проходит и покрывается коркой льда: скорость уменьшается на 3 м до конца её следующего хода; при успехе — половина урона и проходит. Вы выбираете существ, которых кольцо пропускает. На больших уровнях: +1к8 за каждый уровень ячейки выше 6-го.","save":"Телосложение","atk":false,"mech":"Кольцо","theme":"Инея","orig":true,"pack":"spells5.js"},{"id":"sp5-ubezhische-plameni","n":"Убежище Пламени","l":3,"sc":"Ограждение","t":"1 минута","r":"На себя (полусфера 3 м)","c":"ВСМ","m":"Щепоть серы.","d":"8 часов","conc":false,"rit":true,"dmg":"—","cl":["Изобретатель","Колдун","Паладин"],"ds":"Над вами возникает неподвижное убежище для 9 Средних существ: внутри всегда тепло, холод снаружи не проникает, а вход отмечен стеной безвредного огня. Существа и предметы внутри при сотворении могут свободно выходить и входить; прочие — нет. Магия не проходит сквозь стены.","save":"","atk":false,"mech":"Убежище","theme":"Пламени","orig":true,"pack":"spells5.js"},{"id":"sp5-kleymo-kostey","n":"Клеймо Костей","l":1,"sc":"Некромантия","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 колющий","cl":["Следопыт","Паладин","Изобретатель"],"ds":"Следующее ваше попадание атакой оружием наносит дополнительно 2к6 урона (колющий), и цель совершает спасбросок (Телосложение) — при провале она становится хрупкой: следующий дробящий урон по ней до конца её следующего хода увеличивается на 1к6. На больших уровнях: +1к6 за каждый уровень ячейки выше 1-го.","save":"Телосложение","atk":false,"mech":"Клеймо","theme":"Костей","orig":true,"pack":"spells5.js"},{"id":"sp5-avatar-pustoty","n":"Аватар Пустоты","l":6,"sc":"Преобразование","t":"1 бонусное действие","r":"На себя","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"4к8 силовое поле","cl":["Чародей","Колдун"],"ds":"Вы становитесь аватаром стихии: иммунитет к урону «силовое поле», полёт 18 м, 30 временных хитов. Бонусным действием в каждый ход вы метаете снаряд (дальнобойная атака заклинанием, 36 м) на 4к8 урона (силовое поле). На больших уровнях: +10 временных хитов за каждый уровень ячейки выше 6-го.","save":"","atk":true,"mech":"Аватар","theme":"Пустоты","orig":true,"pack":"spells5.js"},{"id":"sp5-aura-zvezd","n":"Аура Звёзд","l":3,"sc":"Ограждение","t":"1 действие","r":"На себя (3 м)","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 излучение","cl":["Бард","Жрец","Друид"],"ds":"Вас окружает аура радиусом 3 м. Союзники в ней имеют сопротивление урону «излучение» и преимущество на спасброски от эффектов, из-за которых цель очерчивается звёздным светом. Враг, начинающий ход в ауре, совершает спасбросок (Мудрость) или получает 2к6 урона (излучение). На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Мудрость","atk":false,"mech":"Аура","theme":"Звёзд","orig":true,"pack":"spells5.js"},{"id":"sp5-golos-razuma","n":"Голос Разума","l":1,"sc":"Очарование","t":"1 действие","r":"На себя","c":"В","m":"","d":"10 минут","conc":false,"rit":false,"dmg":"—","cl":["Чародей","Бард","Колдун"],"ds":"Ваш голос наполняется силой стихии (разума). Вы совершаете с преимуществом проверки Харизмы против существ, которые вас слышат; одно из них по вашему выбору совершает спасбросок Мудрости — при провале оно не может солгать вам до конца действия заклинания. По окончании существо знает, что на него влияли. На больших уровнях: +1 существо, которое не может лгать за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Голос","theme":"Разума","orig":true,"pack":"spells5.js"},{"id":"sp5-carstvo-yada","n":"Царство Яда","l":7,"sc":"Вызов","t":"1 минута","r":"Касание","c":"ВСМ","m":"Жало пчелы.","d":"1 день","conc":false,"rit":false,"dmg":"—","cl":["Колдун","Друид"],"ds":"Вы и до 8 существ переноситесь в полуплан стихии (яда) площадью 150 м², где вы задаёте погоду, свет и простой рельеф. Несогласное существо может избежать переноса спасброском Харизмы. По окончании все возвращаются туда, откуда ушли. Ячейкой 9 уровня — постоянно, с единственным входом.","save":"Телосложение","atk":false,"mech":"Царство","theme":"Яда","orig":true,"pack":"spells5.js"},{"id":"sp5-perenos-voln","n":"Перенос Волн","l":3,"sc":"Вызов","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"—","cl":["Жрец","Друид","Паладин"],"ds":"Вы и до шести согласных существ, держащихся за руки, перемещаетесь по течению на расстояние до 150 м в видимое или известное вам место. На больших уровнях: +150 м за каждый уровень ячейки выше 3-го.","save":"","atk":false,"mech":"Перенос","theme":"Волн","orig":true,"pack":"spells5.js"},{"id":"sp5-balzam-vetra","n":"Бальзам Ветра","l":1,"sc":"Воплощение","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"1 минута","conc":false,"rit":false,"dmg":"—","cl":["Следопыт","Друид","Бард"],"ds":"Существо восстанавливает 1к8 + модификатор заклинательной характеристики хитов и получает сопротивление урону «звук» на 1 минуту. Не действует на нежить и конструктов. На больших уровнях: +1к8 за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Бальзам","theme":"Ветра","orig":true,"pack":"spells5.js"},{"id":"sp5-slovo-kamnya","n":"Слово Камня","l":8,"sc":"Очарование","t":"1 действие","r":"На себя (18 м)","c":"В","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"13к6 дробящий","cl":["Чародей","Бард"],"ds":"Вы произносите истинное слово (камня). Каждый враг в 18 м, слышащий вас, совершает спасбросок Харизмы: 13к6 урона (дробящий) и ошеломление до конца вашего следующего хода при провале, половина урона при успехе.","save":"Харизма","atk":false,"mech":"Слово","theme":"Камня","orig":true,"pack":"spells5.js"},{"id":"sp5-oblik-duhov","n":"Облик Духов","l":4,"sc":"Преобразование","t":"1 действие","r":"На себя","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"2к8 психический","cl":["Бард","Колдун","Жрец"],"ds":"Вы принимаете облик (духов): сопротивление урону «психический» и немагическому оружию, скорость полёта или лазания 12 м, а действием вы совершаете две рукопашные атаки заклинанием по 2к8 урона (психический). Попадание: цель испугана вами до конца её следующего хода. На больших уровнях: +1к8 к одной атаке за каждый уровень ячейки выше 4-го.","save":"","atk":true,"mech":"Облик","theme":"Духов","orig":true,"pack":"spells5.js"},{"id":"sp5-cep-mirazhey","n":"Цепь Миражей","l":2,"sc":"Иллюзия","t":"1 действие","r":"27 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"3к8 психический","cl":["Бард","Колдун","Волшебник"],"ds":"Дальнобойная атака заклинанием: 3к8 урона (психический) при попадании. Затем цепь перескакивает на второе существо в 3 м от первой цели: оно совершает спасбросок (Интеллект) или получает половину этого урона. На больших уровнях: +1к8 и +1 перескок за каждый уровень ячейки выше 2-го.","save":"Интеллект","atk":true,"mech":"Цепь","theme":"Миражей","orig":true,"pack":"spells5.js"},{"id":"sp5-iskra-sveta","n":"Искра Света","l":0,"sc":"Воплощение","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к10 излучение","cl":["Жрец","Друид","Бард"],"ds":"Дальнобойная атака заклинанием по существу или предмету: при попадании 1к10 урона (излучение). Предмет, который никто не несёт, получает двойной урон. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"","atk":true,"mech":"Искра","theme":"Света","orig":true,"pack":"spells5.js"},{"id":"sp5-stena-shipov","n":"Стена Шипов","l":4,"sc":"Преобразование","t":"1 действие","r":"36 м","c":"ВСМ","m":"Шип розы.","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"5к8 колющий","cl":["Следопыт","Чародей","Друид"],"ds":"Стена (шипов) длиной до 18 м, высотой 6 м и толщиной 30 см (или кольцо диаметром 6 м). Существо, впервые за ход проходящее сквозь стену или оканчивающее ход в ней, совершает спасбросок (Сила): 5к8 урона (колющий) при провале (и цель опутывается колючими лозами: скорость 0 до конца её следующего хода), половина при успехе. Стена — слабо заслоняет обзор. На больших уровнях: +1к8 за каждый уровень ячейки выше 4-го.","save":"Сила","atk":false,"mech":"Стена","theme":"Шипов","orig":true,"pack":"spells5.js"},{"id":"sp5-oruzhie-run","n":"Оружие Рун","l":2,"sc":"Преобразование","t":"1 бонусное действие","r":"Касание","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к6 силовое поле","cl":["Изобретатель","Паладин","Следопыт"],"ds":"Немагическое оружие становится магическим с бонусом +1 к атаке и наносит дополнительно 1к6 урона (силовое поле). Один раз в ход при попадании владелец может заставить цель совершить спасбросок (Интеллект): при провале она получает светящуюся руну: следующая атака по ней до конца вашего следующего хода получает +1к4 к броску. Ячейкой 4–5 уровня бонус +2, 6+ уровня — +3.","save":"","atk":false,"mech":"Оружие","theme":"Рун","orig":true,"pack":"spells5.js"},{"id":"sp5-vspyshka-vremeni","n":"Вспышка Времени","l":0,"sc":"Преобразование","t":"1 действие","r":"На себя (1,5 м)","c":"С","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к6 силовое поле","cl":["Бард","Изобретатель","Волшебник"],"ds":"Каждое существо по вашему выбору в пределах 1,5 м совершает спасбросок (Мудрость), получая 1к6 урона (силовое поле) при провале. Не требует видеть цели. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"Мудрость","atk":false,"mech":"Вспышка","theme":"Времени","orig":true,"pack":"spells5.js"},{"id":"sp5-proklyatie-teni","n":"Проклятие Тени","l":4,"sc":"Некромантия","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"2к6 некротика","cl":["Следопыт","Колдун","Чародей"],"ds":"Цель совершает спасбросок Мудрости. При провале ваши атаки и заклинания наносят ей дополнительно 2к6 урона (некротика), а в начале каждого её хода она бросает к4: на 1 она окутывается тенью: помеха на проверки Мудрости (Восприятие) и атаки по существам дальше 9 м. «Снятие проклятия» оканчивает эффект. Ячейкой 5 уровня — 8 часов без концентрации, 7+ уровня — 24 часа.","save":"Мудрость","atk":false,"mech":"Проклятие","theme":"Тени","orig":true,"pack":"spells5.js"},{"id":"sp5-slepok-krovi","n":"Слепок Крови","l":2,"sc":"Преобразование","t":"1 минута","r":"Касание","c":"ВСМ","m":"Капля вашей крови.","d":"8 часов","conc":false,"rit":false,"dmg":"—","cl":["Колдун","Жрец","Паладин"],"ds":"Вы создаёте немагический предмет из застывшей крови, твёрдой как рог размером до куба 1,5 м: инструмент, мост, лестницу, ящик или простое оружие. Предмет имеет КД 15 и 30 хитов; через 8 часов он рассыпается. Ячейкой 4+ уровня предмет держится 24 часа, 6+ уровня — постоянно.","save":"","atk":false,"mech":"Слепок","theme":"Крови","orig":true,"pack":"spells5.js"},{"id":"sp5-maloe-chudo-molniy","n":"Малое Чудо Молний","l":0,"sc":"Воплощение","t":"1 действие","r":"9 м","c":"В","m":"","d":"До 1 часа","conc":false,"rit":false,"dmg":"—","cl":["Изобретатель","Друид","Волшебник"],"ds":"Вы творите мелкое чудо: вызвать безвредный разряд, от которого встают волосы, или зарядить механизм на 1 минуту. Одновременно активны не более трёх эффектов; вы можете окончить любой действием.","save":"","atk":false,"mech":"Малое Чудо","theme":"Молний","orig":true,"pack":"spells5.js"},{"id":"sp5-legion-groma","n":"Легион Грома","l":5,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВСМ","m":"Маленький колокольчик.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"2к6 звук","cl":["Жрец","Следопыт","Друид"],"ds":"Появляются четыре духа (грома): Маленькие, КД 15, хиты 20, скорость 12 м, иммунитет к урону «звук». Каждый атакует заклинанием 1,5 м на 2к6 урона (звук). Действуют в вашу инициативу по вашим мысленным командам (без действия). На больших уровнях: +1 дух за каждый уровень ячейки выше 5-го.","save":"","atk":true,"mech":"Легион","theme":"Грома","orig":true,"pack":"spells5.js"},{"id":"sp5-pechat-ineya","n":"Печать Инея","l":2,"sc":"Ограждение","t":"10 минут","r":"Касание","c":"ВСМ","m":"Кристалл льда.","d":"8 часов","conc":false,"rit":true,"dmg":"3к6 холод","cl":["Паладин","Волшебник","Изобретатель"],"ds":"Вы чертите печать на поверхности или проходе (до 6 м). Когда существо, не названное вами, пересекает её, вы мысленно пробуждаетесь/узнаёте об этом (если вы в пределах 1,5 км), а нарушитель совершает спасбросок (Телосложение): 3к6 урона (холод) при провале, половина при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 2-го.","save":"Телосложение","atk":false,"mech":"Печать","theme":"Инея","orig":true,"pack":"spells5.js"},{"id":"sp5-kope-plameni","n":"Копьё Пламени","l":1,"sc":"Воплощение","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"2к10 огонь","cl":["Чародей","Колдун","Изобретатель"],"ds":"Дальнобойная атака заклинанием: при попадании 2к10 урона (огонь). При критическом попадании копьё пробивает цель и поражает второе существо в 3 м позади неё (обычный бросок атаки). На больших уровнях: +1к10 за каждый уровень ячейки выше 1-го.","save":"","atk":true,"mech":"Копьё","theme":"Пламени","orig":true,"pack":"spells5.js"},{"id":"sp5-svyatilische-kostey","n":"Святилище Костей","l":5,"sc":"Ограждение","t":"10 минут","r":"Касание","c":"ВСМ","m":"Фаланга пальца.","d":"24 часа","conc":false,"rit":false,"dmg":"—","cl":["Жрец","Паладин","Изобретатель"],"ds":"Область радиусом 15 м становится святилищем стихии. Союзники в ней получают +1 к КД и спасброскам; враги, входящие в область, совершают спасбросок (Телосложение) — при провале они становится хрупкой: следующий дробящий урон по ней до конца её следующего хода увеличивается на 1к6 и у них помеха на атаки по союзникам до конца хода. Ячейкой 7+ уровня длится 7 дней, 9 уровня — постоянно.","save":"Телосложение","atk":false,"mech":"Святилище","theme":"Костей","orig":true,"pack":"spells5.js"},{"id":"sp5-vzryv-pustoty","n":"Взрыв Пустоты","l":3,"sc":"Вызов","t":"1 действие","r":"45 м","c":"ВСМ","m":"Чёрная жемчужина.","d":"Мгновенная","conc":false,"rit":false,"dmg":"6к6 силовое поле","cl":["Чародей","Колдун","Бард"],"ds":"Сфера радиусом 6 м: каждое существо совершает спасбросок (Харизма), получая 6к6 урона (силовое поле) при провале (и цель не может телепортироваться и перемещаться между планами до конца её следующего хода) или половину при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Харизма","atk":false,"mech":"Взрыв","theme":"Пустоты","orig":true,"pack":"spells5.js"},{"id":"sp5-volna-zvezd","n":"Волна Звёзд","l":1,"sc":"Прорицание","t":"1 действие","r":"На себя (конус 4,5 м)","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"2к6 излучение","cl":["Бард","Жрец","Друид"],"ds":"Существа в конусе совершают спасбросок (Мудрость): при провале 2к6 урона (излучение) и цель очерчивается звёздным светом: атаки по ней совершаются с преимуществом до конца её следующего хода; при успехе — половина урона без дополнительного эффекта. На больших уровнях: +1к6 за каждый уровень ячейки выше 1-го.","save":"Мудрость","atk":false,"mech":"Волна","theme":"Звёзд","orig":true,"pack":"spells5.js"},{"id":"sp5-svyaz-razuma","n":"Связь Разума","l":5,"sc":"Прорицание","t":"10 минут","r":"Неограниченная","c":"ВСМ","m":"Кусочек мозгового коралла.","d":"Концентрация, до 10 минут","conc":true,"rit":true,"dmg":"—","cl":["Бард","Колдун","Волшебник"],"ds":"Вы вопрошаете спящего или задумчивого существа (вы видите один его сон или мысль), но в любом месте плана, где бывали. Вы видите и слышите место, как если бы находились там, и можете говорить с присутствующими.","save":"","atk":false,"mech":"Связь","theme":"Разума","orig":true,"pack":"spells5.js"},{"id":"sp5-kokon-yada","n":"Кокон Яда","l":3,"sc":"Ограждение","t":"1 действие","r":"18 м","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"—","cl":["Следопыт","Колдун","Друид"],"ds":"Кокон (яда) окружает существо. Согласное существо получает полное укрытие и 2к10 временных хитов. Несогласное совершает спасбросок (Телосложение) — при провале оно опутано, имеет полное укрытие и не может колдовать заклинания с соматическим компонентом; в конце каждого хода повторяет спасбросок. На больших уровнях: +1 цель за каждый уровень ячейки выше 3-го.","save":"Телосложение","atk":false,"mech":"Кокон","theme":"Яда","orig":true,"pack":"spells5.js"}];const D=window.DATA=window.DATA||{};D.spells=D.spells||[];const ids=new Set(D.spells.map(s=>s.id));A.forEach(s=>{if(!ids.has(s.id))D.spells.push(s)});})();
